use futures_util::StreamExt;
use serde::{Deserialize, Serialize};
use std::{collections::HashMap, path::{Path, PathBuf}, process::{Command, Stdio}, sync::{atomic::{AtomicBool, AtomicU64, Ordering}, Arc, Mutex}, time::{Duration, Instant}};
use tauri::Emitter;
use tokio::io::AsyncWriteExt;

#[derive(Clone, Serialize)]
struct ResourceInfo { url:String, kind:String, content_type:Option<String>, filename:Option<String>, size:Option<u64>, final_url:String, status_code:u16 }
#[derive(Clone, Serialize)]
struct DownloadProgress { id:String, url:String, filename:String, downloaded:u64, total:Option<u64>, percent:Option<f64>, speed:u64, status:String, path:Option<String>, error:Option<String> }
#[derive(Deserialize)]
struct YtDlpFormatInfo { filesize:Option<u64>, filesize_approx:Option<u64> }
#[derive(Deserialize)]
struct YtDlpInfo { id:Option<String>, title:Option<String>, ext:Option<String>, filesize:Option<u64>, filesize_approx:Option<u64>, requested_formats:Option<Vec<YtDlpFormatInfo>> }
struct Control { paused:AtomicBool, cancelled:AtomicBool, speed_limit:AtomicU64, child:Mutex<Option<tokio::process::Child>> }
static NEXT_ID:AtomicU64=AtomicU64::new(1);
static CONTROLS:std::sync::OnceLock<Mutex<HashMap<String,Arc<Control>>>>=std::sync::OnceLock::new();
fn controls()->&'static Mutex<HashMap<String,Arc<Control>>>{CONTROLS.get_or_init(||Mutex::new(HashMap::new()))}
fn new_id()->String{format!("download-{}",NEXT_ID.fetch_add(1,Ordering::Relaxed))}
fn get_control(id:&str)->Option<Arc<Control>>{controls().lock().ok()?.get(id).cloned()}
fn remove_control(id:&str){if let Ok(mut m)=controls().lock(){m.remove(id);}}
fn emit(app:&tauri::AppHandle,p:DownloadProgress){let _=app.emit("download-progress",p);}
fn emit_progress(app:&tauri::AppHandle,id:&str,url:&str,filename:&str,downloaded:u64,total:Option<u64>,percent:Option<f64>,speed:u64,status:&str,path:Option<String>,error:Option<String>){emit(app,DownloadProgress{id:id.into(),url:url.into(),filename:filename.into(),downloaded,total,percent,status:status.into(),speed,path,error})}
fn sanitize_filename(filename:&str)->String{let mut cleaned:String=filename.chars().map(|c|match c{'<'|'>'|':'|'"'|'/'|'\\'|'|'|'?'|'*'=>'_',c if c.is_control()=>'_',c=>c}).collect();cleaned=cleaned.trim().trim_matches('.').to_string();let stem=cleaned.split('.').next().unwrap_or("").to_ascii_uppercase();if matches!(stem.as_str(),"CON"|"PRN"|"AUX"|"NUL"|"COM1"|"COM2"|"COM3"|"COM4"|"COM5"|"COM6"|"COM7"|"COM8"|"COM9"|"LPT1"|"LPT2"|"LPT3"|"LPT4"|"LPT5"|"LPT6"|"LPT7"|"LPT8"|"LPT9"){cleaned.insert(0,'_');}if cleaned.is_empty(){"download".into()}else{cleaned}}
fn truncate_utf8(value:&str,max_bytes:usize)->String{if value.len()<=max_bytes{return value.to_string()}let mut end=max_bytes;while end>0&&!value.is_char_boundary(end){end-=1;}value[..end].to_string()}
fn safe_media_filename(title:&str,extension:&str)->String{let title=sanitize_filename(title);let extension=extension.trim_start_matches('.').to_ascii_lowercase();let extension=if extension.is_empty(){"bin".to_string()}else{sanitize_filename(&extension)};let suffix=format!(".{extension}");format!("{}{}",truncate_utf8(&title,100usize.saturating_sub(suffix.len()).max(1)),suffix)}
fn filename_from_url(url:&str)->Option<String>{let p=reqwest::Url::parse(url).ok()?;let s=p.path_segments()?.filter(|v|!v.is_empty()).next_back()?;let d=percent_encoding::percent_decode_str(s).decode_utf8().ok()?.to_string();let d=sanitize_filename(&d);if d=="download"{None}else{Some(d)}}
fn filename_from_content_disposition(v:&str)->Option<String>{for part in v.split(';').skip(1){let part=part.trim();if let Some(f)=part.strip_prefix("filename*=UTF-8''"){let d=percent_encoding::percent_decode_str(f).decode_utf8().ok()?.to_string();if !d.is_empty(){return Some(sanitize_filename(&d));}}if let Some(f)=part.strip_prefix("filename="){let f=f.trim().trim_matches('"');if !f.is_empty(){return Some(sanitize_filename(f));}}}None}
fn extension_for_content_type(v:&str)->Option<&'static str>{let m=v.split(';').next()?.trim().to_ascii_lowercase();match m.as_str(){"image/jpeg"=>Some("jpg"),"image/png"=>Some("png"),"image/gif"=>Some("gif"),"image/webp"=>Some("webp"),"image/svg+xml"=>Some("svg"),"video/mp4"=>Some("mp4"),"video/webm"=>Some("webm"),"video/quicktime"=>Some("mov"),"video/x-matroska"=>Some("mkv"),"audio/mpeg"=>Some("mp3"),"audio/mp4"=>Some("m4a"),"audio/wav"=>Some("wav"),"audio/ogg"=>Some("ogg"),"application/pdf"=>Some("pdf"),"application/zip"=>Some("zip"),"application/gzip"=>Some("gz"),"application/x-rar-compressed"=>Some("rar"),"application/json"=>Some("json"),"text/plain"=>Some("txt"),_=>None}}
fn ensure_extension(filename:String,ct:&str)->String{if Path::new(&filename).extension().is_some(){filename}else if let Some(e)=extension_for_content_type(ct){format!("{filename}.{e}")}else{filename}}
fn is_known_media_page(url:&reqwest::Url)->bool{let h=url.host_str().unwrap_or("").to_ascii_lowercase();let h=h.strip_prefix("www.").unwrap_or(&h);["youtube.com","youtu.be","youtube-nocookie.com","vimeo.com","dailymotion.com","tiktok.com","instagram.com","facebook.com","soundcloud.com"].iter().any(|d|h==*d||h.ends_with(&format!(".{d}")))}
fn resource_kind(ct:Option<&str>,url:&reqwest::Url)->&'static str{if is_known_media_page(url){return "media_page"}let m=ct.and_then(|v|v.split(';').next()).unwrap_or("").trim().to_ascii_lowercase();if m=="text/html"||m=="application/xhtml+xml"{return "webpage"}if m.starts_with("image/"){return "image"}if m.starts_with("video/"){return "video"}if m.starts_with("audio/"){return "audio"}if m.starts_with("text/")||m=="application/json"||m=="application/javascript"{return "webpage"}let p=url.path().to_ascii_lowercase();if ["jpg","jpeg","png","gif","webp","svg"].iter().any(|e|p.ends_with(&format!(".{e}"))){return "image"}if ["mp4","webm","mov","mkv","avi"].iter().any(|e|p.ends_with(&format!(".{e}"))){return "video"}if ["mp3","m4a","wav","flac","ogg"].iter().any(|e|p.ends_with(&format!(".{e}"))){return "audio"}"file"}
fn total_size_from_response(r:&reqwest::Response)->Option<u64>{if let Some(v)=r.headers().get(reqwest::header::CONTENT_RANGE){if let Ok(v)=v.to_str(){if let Some(t)=v.rsplit('/').next(){if t!="*"{if let Ok(n)=t.parse(){return Some(n)}}}}}r.content_length()}
fn available_path(d:&Path,f:&str)->PathBuf{let p=d.join(f);if !p.exists(){return p}let x=Path::new(f);let s=x.file_stem().and_then(|v|v.to_str()).unwrap_or("download");let e=x.extension().and_then(|v|v.to_str());for i in 1..10000{let n=match e{Some(e)=>format!("{s} ({i}).{e}"),None=>format!("{s} ({i})")};let c=d.join(n);if !c.exists(){return c}}d.join("download.bin")}
fn filename_from_response(r:&reqwest::Response)->Option<String>{if let Some(v)=r.headers().get(reqwest::header::CONTENT_DISPOSITION){if let Ok(v)=v.to_str(){if let Some(f)=filename_from_content_disposition(v){return Some(f)}}}filename_from_url(r.url().as_str())}
fn yt_dlp_available()->bool{Command::new("yt-dlp").arg("--version").output().map(|o|o.status.success()).unwrap_or(false)}
fn inspect_media_with_yt_dlp(url:&str)->Result<YtDlpInfo,String>{if !yt_dlp_available(){return Err("YouTube/media extraction requires yt-dlp. Install yt-dlp, restart Monk3i, and try again.".into())}let o=Command::new("yt-dlp").env("PYTHONIOENCODING","utf-8:replace").env("PYTHONUTF8","1").args(["--dump-single-json","--no-warnings","--no-playlist",url]).output().map_err(|e|format!("Could not start yt-dlp: {e}"))?;if !o.status.success(){let m=String::from_utf8_lossy(&o.stderr).trim().to_string();return Err(if m.is_empty(){"yt-dlp could not inspect this media URL.".into()}else{m})}serde_json::from_slice(&o.stdout).map_err(|e|format!("Could not read media information: {e}"))}
fn media_expected_total(info:&YtDlpInfo)->Option<u64>{if let Some(n)=info.filesize.or(info.filesize_approx){return Some(n)}let formats=info.requested_formats.as_ref()?;let mut sum=0u64;for f in formats{sum=sum.saturating_add(f.filesize.or(f.filesize_approx)?);}if sum>0{Some(sum)}else{None}}
#[tauri::command]
async fn inspect_url(url:String)->Result<ResourceInfo,String>{let url=url.trim().to_string();let parsed=reqwest::Url::parse(&url).map_err(|_|"Please enter a valid URL.".to_string())?;if !matches!(parsed.scheme(),"http"|"https"){return Err("Only HTTP and HTTPS URLs are supported.".into())}if is_known_media_page(&parsed){let info=inspect_media_with_yt_dlp(&url)?;return Ok(ResourceInfo{url:url.clone(),kind:"media_page".into(),content_type:None,filename:info.title.clone().map(|t|safe_media_filename(&t,info.ext.as_deref().unwrap_or("mp4"))),size:media_expected_total(&info),final_url:url,status_code:200})}let c=reqwest::Client::builder().user_agent("Monk3i Download Manager/0.1").redirect(reqwest::redirect::Policy::limited(10)).build().map_err(|e|e.to_string())?;let r=match c.head(parsed.clone()).send().await{Ok(r) if r.status().is_success()||r.status().is_redirection()=>r,_=>c.get(parsed).header(reqwest::header::RANGE,"bytes=0-0").send().await.map_err(|e|e.to_string())?};let ct=r.headers().get(reqwest::header::CONTENT_TYPE).and_then(|v|v.to_str().ok()).map(str::to_string);let filename=filename_from_response(&r).map(|n|ensure_extension(n,ct.as_deref().unwrap_or("")));let size=total_size_from_response(&r);let final_url=r.url().to_string();let kind=resource_kind(ct.as_deref(),r.url()).to_string();Ok(ResourceInfo{url,kind,content_type:ct,filename,size,final_url,status_code:r.status().as_u16()})}
async fn media_partial_size(temp_dir:&Path)->u64{let mut entries=match tokio::fs::read_dir(temp_dir).await{Ok(v)=>v,Err(_)=>return 0};let mut total=0u64;while let Ok(Some(entry))=entries.next_entry().await{let p=entry.path();if !p.is_file(){continue}let name=p.file_name().and_then(|v|v.to_str()).unwrap_or("");if name.ends_with(".part")||name.ends_with(".ytdl"){if let Ok(meta)=entry.metadata().await{total=total.saturating_add(meta.len())}}}total}
async fn find_media_output(temp_dir:&Path,media_id:&str)->Option<PathBuf>{let mut entries=tokio::fs::read_dir(temp_dir).await.ok()?;let mut fallback=None;while let Ok(Some(entry))=entries.next_entry().await{let p=entry.path();if !p.is_file(){continue}let filename=p.file_name().and_then(|v|v.to_str()).unwrap_or("");if filename.ends_with(".part")||filename.ends_with(".ytdl"){continue}let stem=p.file_stem().and_then(|v|v.to_str()).unwrap_or("");if stem==media_id{return Some(p)}if fallback.is_none()&&!filename.starts_with('.') {fallback=Some(p)}}fallback}
async fn wait_if_paused(control:&Arc<Control>)->bool{while control.paused.load(Ordering::Relaxed)&&!control.cancelled.load(Ordering::Relaxed){tokio::time::sleep(Duration::from_millis(200)).await}!control.cancelled.load(Ordering::Relaxed)}
fn kill_media_child(control:&Arc<Control>){if let Ok(mut slot)=control.child.lock(){if let Some(child)=slot.as_mut(){let _=child.start_kill();}}}
async fn run_media(app:tauri::AppHandle,id:String,url:String,directory:PathBuf,control:Arc<Control>){
 let info=match inspect_media_with_yt_dlp(&url){Ok(v)=>v,Err(e)=>{emit_progress(&app,&id,&url,"Media download",0,None,None,0,"error",None,Some(e));remove_control(&id);return}};let media_id=info.id.clone().unwrap_or_else(||id.clone());let title=info.title.clone().unwrap_or_else(||"Downloaded media".into());let total=media_expected_total(&info);let temp_dir=directory.join(format!(".monk3i-{id}"));if let Err(e)=tokio::fs::create_dir_all(&temp_dir).await{emit_progress(&app,&id,&url,"Media download",0,total,None,0,"error",None,Some(format!("Could not create temporary download folder: {e}")));remove_control(&id);return}let template=temp_dir.join("%(id)s.%(ext)s");
 loop{
  if control.cancelled.load(Ordering::Relaxed){kill_media_child(&control);let _=tokio::fs::remove_dir_all(&temp_dir).await;remove_control(&id);return}
  if control.paused.load(Ordering::Relaxed){let d=media_partial_size(&temp_dir).await;let p=total.map(|t|if t>0{(d as f64*100.0/t as f64).min(99.9)}else{0.0});emit_progress(&app,&id,&url,"Media download",d,total,p,0,"paused",None,None);if !wait_if_paused(&control).await{let _=tokio::fs::remove_dir_all(&temp_dir).await;remove_control(&id);return}}
  let limit=control.speed_limit.load(Ordering::Relaxed);
  let mut cmd=tokio::process::Command::new("yt-dlp");cmd.env("PYTHONIOENCODING","utf-8:replace").env("PYTHONUTF8","1").args(["--no-playlist","--newline","--continue","-f","bv*+ba/b","--merge-output-format","mp4","--print","after_move:filepath","-o"]).arg(template.to_string_lossy().to_string());if limit>0{cmd.args(["--limit-rate",&limit.to_string()]);}let child=match cmd.arg(&url).stdout(Stdio::null()).stderr(Stdio::null()).spawn(){Ok(c)=>c,Err(e)=>{let _=tokio::fs::remove_dir_all(&temp_dir).await;emit_progress(&app,&id,&url,"Media download",0,total,None,0,"error",None,Some(format!("Could not start yt-dlp: {e}")));remove_control(&id);return}};if let Ok(mut slot)=control.child.lock(){*slot=Some(child)}
  let mut last_downloaded=media_partial_size(&temp_dir).await;let mut last_sample=Instant::now();let mut last_emit=Instant::now()-Duration::from_secs(1);let mut killed=false;
  loop{if control.cancelled.load(Ordering::Relaxed)||control.paused.load(Ordering::Relaxed){killed=true;kill_media_child(&control)}tokio::time::sleep(Duration::from_millis(350)).await;let now=Instant::now();let downloaded=media_partial_size(&temp_dir).await;let elapsed=now.duration_since(last_sample).as_secs_f64().max(0.001);let speed=((downloaded.saturating_sub(last_downloaded)) as f64/elapsed) as u64;let percent=total.map(|t|if t>0{(downloaded as f64*100.0/t as f64).min(99.9)}else{0.0});if downloaded!=last_downloaded||last_emit.elapsed()>=Duration::from_millis(700){emit_progress(&app,&id,&url,"Downloading media...",downloaded,total,percent,speed,"downloading",None,None);last_emit=now}last_downloaded=downloaded;last_sample=now;let exited={let mut slot=control.child.lock().unwrap();match slot.as_mut(){Some(c)=>match c.try_wait(){Ok(Some(_))=>true,Ok(None)=>false,Err(_)=>true},None=>true}};if exited{break}}
  let child_to_wait={let mut slot=control.child.lock().unwrap();slot.take()};let status=if let Some(mut c)=child_to_wait{c.wait().await.ok()}else{None};
  if control.cancelled.load(Ordering::Relaxed){let _=tokio::fs::remove_dir_all(&temp_dir).await;emit_progress(&app,&id,&url,"Media download",last_downloaded,total,None,0,"cancelled",None,None);remove_control(&id);return}
  if control.paused.load(Ordering::Relaxed)||killed{if control.paused.load(Ordering::Relaxed){let p=total.map(|t|if t>0{last_downloaded as f64*100.0/t as f64}else{0.0});emit_progress(&app,&id,&url,"Media download",last_downloaded,total,p,0,"paused",None,None);if !wait_if_paused(&control).await{let _=tokio::fs::remove_dir_all(&temp_dir).await;remove_control(&id);return}}continue}
  if status.map(|s|s.success()).unwrap_or(false){let source_path=match find_media_output(&temp_dir,&media_id).await{Some(p)=>p,None=>{let _=tokio::fs::remove_dir_all(&temp_dir).await;emit_progress(&app,&id,&url,"Media download",last_downloaded,total,Some(100.0),0,"error",None,Some("yt-dlp completed, but Monk3i could not locate the downloaded media file.".into()));remove_control(&id);return}};let ext=source_path.extension().and_then(|v|v.to_str()).or(info.ext.as_deref()).unwrap_or("mp4");let filename=safe_media_filename(&title,ext);let final_path=available_path(&directory,&filename);if let Err(e)=tokio::fs::rename(&source_path,&final_path).await{let _=tokio::fs::remove_dir_all(&temp_dir).await;emit_progress(&app,&id,&url,&filename,last_downloaded,total,None,0,"error",None,Some(format!("Could not finalize downloaded media: {e}")));remove_control(&id);return}let final_total=tokio::fs::metadata(&final_path).await.map(|m|m.len()).ok().or(total);let _=tokio::fs::remove_dir_all(&temp_dir).await;emit_progress(&app,&id,&url,final_path.file_name().and_then(|v|v.to_str()).unwrap_or("Downloaded media"),final_total.unwrap_or(last_downloaded),final_total,Some(100.0),0,"completed",Some(final_path.to_string_lossy().to_string()),None);remove_control(&id);return}
  let _=tokio::fs::remove_dir_all(&temp_dir).await;emit_progress(&app,&id,&url,"Media download",last_downloaded,total,None,0,"error",None,Some("Media download failed.".into()));remove_control(&id);return;
 }
}
#[tauri::command]
async fn start_download(app:tauri::AppHandle,url:String)->Result<String,String>{let url=url.trim().to_string();let parsed=reqwest::Url::parse(&url).map_err(|_|"Please enter a valid URL.".to_string())?;if !matches!(parsed.scheme(),"http"|"https"){return Err("Only HTTP and HTTPS URLs are supported.".into())}let id=new_id();let control=Arc::new(Control{paused:AtomicBool::new(false),cancelled:AtomicBool::new(false),speed_limit:AtomicU64::new(0),child:Mutex::new(None)});controls().lock().unwrap().insert(id.clone(),control.clone());if is_known_media_page(&parsed){if !yt_dlp_available(){remove_control(&id);return Err("YouTube/media extraction requires yt-dlp. Install yt-dlp, restart Monk3i, and try again.".into())}let d=dirs::download_dir().or_else(dirs::home_dir).ok_or_else(||"Could not find a Downloads folder.".to_string())?;std::fs::create_dir_all(&d).map_err(|e|e.to_string())?;emit_progress(&app,&id,&url,"Preparing media...",0,None,Some(0.0),0,"downloading",None,None);tokio::spawn(run_media(app,id.clone(),url,d,control));return Ok(id)}let client=reqwest::Client::builder().user_agent("Monk3i Download Manager/0.1").redirect(reqwest::redirect::Policy::limited(10)).build().map_err(|e|e.to_string())?;let response=client.get(parsed).send().await.map_err(|e|e.to_string())?.error_for_status().map_err(|e|e.to_string())?;let ct=response.headers().get(reqwest::header::CONTENT_TYPE).and_then(|v|v.to_str().ok()).unwrap_or("").to_string();let kind=resource_kind(Some(&ct),response.url());if kind=="webpage"||kind=="media_page"{remove_control(&id);return Err("This URL points to a webpage, not a direct file.".into())}let filename=filename_from_response(&response).map(|n|ensure_extension(n,&ct)).unwrap_or_else(||extension_for_content_type(&ct).map(|e|format!("download.{e}")).unwrap_or_else(||"download.bin".into()));let d=dirs::download_dir().or_else(dirs::home_dir).ok_or_else(||"Could not find a Downloads folder.".to_string())?;std::fs::create_dir_all(&d).map_err(|e|e.to_string())?;let path=available_path(&d,&filename);let total=total_size_from_response(&response);emit_progress(&app,&id,&url,&filename,0,total,total.map(|_|0.0),0,"downloading",Some(path.to_string_lossy().to_string()),None);let mut file=tokio::fs::File::create(&path).await.map_err(|e|e.to_string())?;let mut stream=response.bytes_stream();let mut downloaded=0u64;let started=Instant::now();while let Some(chunk)=stream.next().await{if control.cancelled.load(Ordering::Relaxed){drop(file);let _=tokio::fs::remove_file(&path).await;emit_progress(&app,&id,&url,&filename,downloaded,total,total.map(|t|if t>0{downloaded as f64*100.0/t as f64}else{0.0}),0,"cancelled",Some(path.to_string_lossy().to_string()),None);remove_control(&id);return Ok(id)}if control.paused.load(Ordering::Relaxed){emit_progress(&app,&id,&url,&filename,downloaded,total,total.map(|t|if t>0{downloaded as f64*100.0/t as f64}else{0.0}),0,"paused",Some(path.to_string_lossy().to_string()),None);if !wait_if_paused(&control).await{drop(file);let _=tokio::fs::remove_file(&path).await;emit_progress(&app,&id,&url,&filename,downloaded,total,total.map(|t|if t>0{downloaded as f64*100.0/t as f64}else{0.0}),0,"cancelled",Some(path.to_string_lossy().to_string()),None);remove_control(&id);return Ok(id)}}let chunk=chunk.map_err(|e|e.to_string())?;file.write_all(&chunk).await.map_err(|e|e.to_string())?;downloaded+=chunk.len() as u64;let limit=control.speed_limit.load(Ordering::Relaxed);if limit>0{let target=downloaded as f64/limit as f64;let elapsed=started.elapsed().as_secs_f64();if target>elapsed{tokio::time::sleep(Duration::from_secs_f64(target-elapsed)).await}}let speed=(downloaded as f64/started.elapsed().as_secs_f64().max(0.001)) as u64;emit_progress(&app,&id,&url,&filename,downloaded,total,total.map(|t|if t>0{downloaded as f64*100.0/t as f64}else{0.0}),speed,"downloading",Some(path.to_string_lossy().to_string()),None)}file.flush().await.map_err(|e|e.to_string())?;emit_progress(&app,&id,&url,&filename,downloaded,total,Some(100.0),0,"completed",Some(path.to_string_lossy().to_string()),None);remove_control(&id);Ok(id)}
#[tauri::command]
fn pause_download(id:String)->Result<(),String>{let c=get_control(&id).ok_or_else(||"Download not found.".to_string())?;c.paused.store(true,Ordering::Relaxed);kill_media_child(&c);Ok(())}
#[tauri::command]
fn resume_download(id:String)->Result<(),String>{let c=get_control(&id).ok_or_else(||"Download not found.".to_string())?;if c.cancelled.load(Ordering::Relaxed){return Err("Download has been cancelled.".into())}c.paused.store(false,Ordering::Relaxed);Ok(())}
#[tauri::command]
fn cancel_download(id:String)->Result<(),String>{let c=get_control(&id).ok_or_else(||"Download not found.".to_string())?;c.cancelled.store(true,Ordering::Relaxed);c.paused.store(false,Ordering::Relaxed);kill_media_child(&c);Ok(())}
#[tauri::command]
fn set_speed_limit(id:String,bytes_per_second:u64)->Result<(),String>{let c=get_control(&id).ok_or_else(||"Download not found.".to_string())?;c.speed_limit.store(bytes_per_second,Ordering::Relaxed);Ok(())}
#[cfg_attr(mobile,tauri::mobile_entry_point)]
pub fn run(){tauri::Builder::default().plugin(tauri_plugin_opener::init()).invoke_handler(tauri::generate_handler![inspect_url,start_download,pause_download,resume_download,cancel_download,set_speed_limit]).run(tauri::generate_context!()).expect("error while running Tauri application");}